const $ = (id) => document.getElementById(id);
const route = location.pathname.split('/').pop().toLowerCase().replace(/\.html$/, '');
const role = route === 'audience' ? 'audience' : route === 'participant' ? 'participant' : 'admin';
let S = {}, ADMIN_TOKEN = localStorage.getItem('quizMasterAdminToken') || '', TEAM_TOKEN = sessionStorage.getItem('quizMasterTeamToken') || '';
let draftAnswers = {}, activeQuestionSet = [], activeRound = null, roundStartedAt = 0, pollTimer = null, timeTimer = null, saving = false, pendingMedia = null, lastAudienceMode = '', lastAudienceQuestionId = '', lastAudienceRanks = '', animateAudienceRanks = false;
const root = $('app');
const palette = ['#6857e8','#e76f51','#1c9c89','#d18a2b','#3975c7','#b64e90','#57983e','#7b5bb5'];
const logoSet = ['🚀','🦁','⚡','🌟','🦊','🏆','🎯','🐺','🦉','🐉','🌈','🧠'];
const icons = {Overview:'▦',Teams:'♧',Questions:'▤',Rounds:'◷',Projector:'▣',Settings:'⚙'};

function esc(v=''){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function jsarg(v=''){return esc(JSON.stringify(String(v)))}
function fmtRound(n){return `Round ${n}`}
function roundMinutes(value){const p=String(value||'10:00').split(':').map(Number);return p.length>1?(p[0]+p[1]/60):p[0]||10}
function roundTime(minutes){const s=Math.max(1,Math.round((Number(minutes)||10)*60));return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function rnd(chars,len){const b=new Uint8Array(len);crypto.getRandomValues(b);return [...b].map(x=>chars[x%chars.length]).join('')}
function loginCode(){return rnd('ABCDEFGHJKLMNPQRSTUVWXYZ23456789',8)}
function roundPassword(){return rnd('ABCDEFGHJKLMNPQRSTUVWXYZ23456789',8)}
function uniqueRoundPassword(teamCode){let p;do{p=roundPassword()}while((S.teams||[]).some(t=>t.code===p)||p===teamCode||Object.values(S.passwords||{}).includes(p));return p}
function logoFor(name){let h=0;for(const c of String(name||''))h=(h*31+c.charCodeAt(0))>>>0;return {logo:logoSet[h%logoSet.length],logoColor:palette[h%palette.length]}}
function uniqueLogoFor(name,teams=S.teams||[]){let h=0;for(const c of String(name||''))h=(h*31+c.charCodeAt(0))>>>0;for(let step=0;step<logoSet.length*palette.length;step++){const k=(h+step)%(logoSet.length*palette.length),candidate={logo:logoSet[Math.floor(k/palette.length)],logoColor:palette[k%palette.length]};if(!teams.some(t=>t.logo===candidate.logo&&t.logoColor===candidate.logoColor))return candidate}return logoFor(name)}
function logo(team,size=34){const g=team?.logo?{logo:team.logo,logoColor:team.logoColor||palette[0]}:logoFor(team?.name);return `<span class="team-logo" style="--logo-color:${esc(g.logoColor)};width:${size}px;height:${size}px">${esc(g.logo)}</span>`}
function mediaMarkup(url,type=''){if(!url||(!String(url).startsWith('/media/')&&!/^https?:\/\//i.test(String(url))))return '';const yt=String(url).match(/(?:youtube\.com\/watch\?v=|youtu\.be\/|youtube\.com\/embed\/)([A-Za-z0-9_-]{6,})/);if(yt)return `<iframe class="question-media" src="https://www.youtube-nocookie.com/embed/${esc(yt[1])}" title="Question video" allowfullscreen></iframe>`;return type.startsWith('video/')||/\.(mp4|webm)(?:\?|$)/i.test(url)?`<video class="question-media" controls playsinline preload="metadata" src="${esc(url)}"></video>`:`<img class="question-media" src="${esc(url)}" alt="Question media">`}
function toast(message){let el=document.querySelector('.toast');if(!el){el=document.createElement('div');el.className='toast';document.body.append(el)}el.textContent=message;el.classList.add('show');clearTimeout(el._timer);el._timer=setTimeout(()=>el.classList.remove('show'),2800)}
async function api(path,method='GET',data){const token=path.startsWith('/api/team')?TEAM_TOKEN:ADMIN_TOKEN;const res=await fetch(path,{method,headers:{'content-type':'application/json',...(token?{authorization:`Bearer ${token}`}:{})},...(data===undefined?{}:{body:JSON.stringify(data)})});if(path.endsWith('.csv'))return res;if(res.status===204)return null;const out=await res.json().catch(()=>({}));if(!res.ok)throw Error(out.error||`Request failed (${res.status})`);return out}
function save(){if(role!=='admin'||!ADMIN_TOKEN)return;clearTimeout(save.timer);save.timer=setTimeout(async()=>{saving=true;try{await api('/api/admin/state','PUT',S)}catch(e){toast(`Save failed: ${e.message}`)}finally{saving=false}},220)}
function header(title,subtitle,action=''){return `<div class="welcome"><div><div class="eyebrow">QUIZ MASTER · ADMIN</div><h1>${esc(title)}</h1><p class="sub">${esc(subtitle)}</p></div>${action}</div>`}
function btn(label,action,kind=''){return `<button class="btn ${kind}" onclick="${action}">${label}</button>`}
function shell(content,current='Overview'){return `<header class="topbar"><div><div class="brand"><span class="mark">QM</span><span>QUIZ <b>MASTER</b></span></div><p class="tagline">Tournament control centre</p></div><div class="bar-right"><span class="pill ${S.running?'':'paused'}">${S.running?'● Tournament live':'Tournament paused'}</span><button class="btn light tiny" onclick="logoutAdmin()">Sign out</button></div></header><div class="layout"><aside class="sidebar"><div class="side-label">Manage tournament</div>${['Overview','Teams','Questions','Rounds','Projector','Settings'].map(x=>`<button class="nav ${current===x?'active':''}" onclick="go('${x}')"><span class="ico">${icons[x]}</span>${x}${x==='Teams'?`<span class="count">${S.teams?.length||0}</span>`:''}</button>`).join('')}<div class="side-bottom">${esc(S.quizName||'QUIZ MASTER')}<br>Admin workspace</div></aside><main class="main">${content}</main></div>`}
function stat(label,value,caption,icon){return `<article class="card stat"><div class="stat-label">${label}</div><span class="stat-icon">${icon}</span><div class="stat-value">${value}</div><div class="stat-foot">${caption}</div></article>`}
function sortedTeams(){return [...(S.teams||[])].sort((a,b)=>(Number(b.points)||0)-(Number(a.points)||0)||(role==='audience'?0:(Number(a.speed)||Infinity)-(Number(b.speed)||Infinity)))}
function leaderboardTable(showSpeed=false){const teams=sortedTeams();return `<div class="table-wrap"><table class="table"><thead><tr><th>Rank</th><th>Team</th><th>Points</th><th>Progress</th>${showSpeed?'<th>Answer time · admin</th>':''}<th>Status</th></tr></thead><tbody>${teams.length?teams.map((t,i)=>`<tr class="leader-row ${role==='audience'&&animateAudienceRanks?'rank-shift':''}" style="--rank:${i}"><td class="rank">${['🥇','🥈','🥉'][i]||String(i+1).padStart(2,'0')}</td><td><div class="team-cell">${logo(t,32)}${esc(t.name)}</div></td><td class="pts">${Number(t.points)||0}</td><td>${esc(t.progress||`0/${S.rounds?.length||0}`)}</td>${showSpeed?`<td>${t.speed?`${(Number(t.speed)/1000).toFixed(1)} sec`:'—'}</td>`:''}<td><span class="badge ${t.status==='Complete'?'live':''}">${esc(t.status||'Registered')}</span></td></tr>`).join(''):`<tr><td colspan="6" class="empty-cell">Add teams to start the leaderboard.</td></tr>`}</tbody></table></div>`}
function overview(){const complete=(S.teams||[]).filter(t=>t.status==='Complete').length,active=(S.rounds||[]).find(r=>r.active);return shell(`${header('Tournament overview','Manage teams, questions, timing and what appears on the projector.',btn('Open audience screen','openAudience()','light'))}<div class="stats">${stat('Teams',S.teams.length,'Registered teams','♧')}${stat('Questions',S.questions.length,'In your question bank','▤')}${stat('Rounds',(S.rounds||[]).length,'Configured rounds','◷')}${stat('Finished',`${complete}/${S.teams.length||0}`,'Teams through every round','✓')}</div><div class="panels"><section class="card panel"><div class="panel-head"><h2>Rounds</h2><button class="small-link" onclick="go('Rounds')">Configure rounds →</button></div>${(S.rounds||[]).map(r=>`<div class="round-row"><div class="round-n">${r.n}</div><div><div class="round-name">${esc(r.name)}</div><div class="round-desc">${Number(r.q)||0} questions · ${roundMinutes(r.time)} minutes</div></div><span class="badge ${r.active?'live':''}">${esc(r.status||'Locked')}</span></div>`).join('')}</section><section class="card panel"><div class="panel-head"><h2>Current activity</h2><span class="badge ${active?'live':''}">${active?'ROUND LIVE':'WAITING'}</span></div><p class="sub">${active?`${esc(active.name)} is open. Its timer closes the round automatically.`:'Start Round 1 when your teams and questions are ready.'}</p><div class="quick-actions">${btn('＋ Add team',"go('Teams')",'tiny')}${btn('＋ Add question',"go('Questions')",'tiny light')}${btn('⛶ Projector',"openAudience()",'tiny light')}</div><p class="sub small-note">The leaderboard updates on the audience screen every few seconds. Speed is used only as an admin tie-breaker; it is not added to answer points.</p></section></div><section class="card table-panel"><div class="panel-head"><h2>Live leaderboard</h2><span class="badge live">Admin view · speed available</span></div>${leaderboardTable(true)}</section>`,'Overview')}

function teamsPage(){return shell(`${header('Teams & login access','Add teams one at a time or import a CSV. Each team gets a unique login code and logo.',`<div class="toolbar">${btn('＋ Add team','addTeam()')}${btn('↑ Upload team CSV',"$('teamFile').click()",'light')}<input id="teamFile" type="file" accept=".csv,text/csv" hidden onchange="importTeams(this.files[0])">${btn('↓ Download codes','downloadTeamCodes()','light')}</div>`)}<section class="card table-panel"><div class="panel-head"><h2>Registered teams</h2><span class="badge">${S.teams.length} teams</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Team</th><th>Login password</th><th>Points</th><th>Progress</th><th>Speed · admin</th><th>Manage</th></tr></thead><tbody>${S.teams.length?S.teams.map(t=>`<tr><td><div class="team-cell">${logo(t,36)}<span>${esc(t.name)}</span></div></td><td><code>${esc(t.code)}</code> <button class="small-link" onclick="copyText('${esc(t.code)}')">Copy</button></td><td class="pts">${Number(t.points)||0}</td><td>${esc(t.progress||`0/${S.rounds.length}`)}</td><td>${t.speed?`${(Number(t.speed)/1000).toFixed(1)} sec`:'—'}</td><td><button class="small-link" onclick="resetTeamCode('${esc(t.code)}')">Reset code</button> <button class="small-link danger" onclick="removeTeam('${esc(t.code)}')">Remove</button></td></tr>`).join(''):`<tr><td colspan="6" class="empty-cell">No teams yet. Choose “Add team” to create the first team.</td></tr>`}</tbody></table></div></section><section class="card control-box" style="margin-top:16px"><h3>How team access works</h3><p class="sub">Give each team its login password from the table. Round 1 needs no round password. When you open Round 2 or later, Quiz Master generates a different password for every team; share each password only with its matching team.</p></section>`,'Teams')}
function addTeam(){const name=prompt('Team name');if(!name||!name.trim())return;const normalized=name.trim();if(S.teams.some(t=>t.name.toLowerCase()===normalized.toLowerCase()))return toast('A team with that name already exists.');let code=loginCode();while(S.teams.some(t=>t.code===code)||Object.values(S.passwords||{}).includes(code))code=loginCode();const active=(S.rounds||[]).find(r=>r.active),progress=active?Math.max(0,active.n-1):0,g=uniqueLogoFor(normalized),team={name:normalized,code,points:0,progress:`${progress}/${S.rounds.length}`,status:active?`In round ${active.n}`:'Registered',speed:0,...g};if(active?.n>1)S.passwords[`${active.n}-${code}`]=uniqueRoundPassword(code);S.teams.push(team);save();render();toast(`Created ${normalized}. Login password: ${code}`)}
function resetTeamCode(old){const t=S.teams.find(x=>x.code===old);if(!t)return;let code=loginCode();while(S.teams.some(x=>x.code===code)||Object.values(S.passwords||{}).includes(code))code=loginCode();for(const store of [S.passwords,S.roundAccess])if(store)for(const key of Object.keys(store))if(key.endsWith('-'+old)){const next=key.slice(0,-old.length)+code;store[next]=store[key];delete store[key]}t.code=code;save();render();toast(`New login password for ${t.name}: ${code}`)}function removeTeam(code){const t=S.teams.find(x=>x.code===code);if(!t||!confirm(`Remove ${t.name} and its access? Past answers remain in the export.`))return;S.teams=S.teams.filter(x=>x.code!==code);delete S.passwords[`${S.rounds.find(r=>r.active)?.n}-${code}`];save();render()}
function copyText(text){navigator.clipboard?.writeText(text).then(()=>toast('Copied')).catch(()=>toast(text))}
function download(name,text,type='text/csv'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function csvCell(v){return `"${String(v??'').replaceAll('"','""')}"`}
function downloadTeamCodes(){download('quiz-master-team-logins.csv',['Team name,Team login password,Logo',...S.teams.map(t=>[t.name,t.code,t.logo||logoFor(t.name).logo].map(csvCell).join(','))].join('\r\n'))}
function parseCsv(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'&&quoted&&text[i+1]==='"'){cell+='"';i++}else if(c==='"')quoted=!quoted;else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell=''}else cell+=c}if(cell||row.length){row.push(cell);if(row.some(x=>x.trim()))rows.push(row)}return rows}
function importTeams(file){if(!file)return;const reader=new FileReader();reader.onload=()=>{const rows=parseCsv(String(reader.result||''));let count=0;for(let i=0;i<rows.length;i++){const name=(rows[i][0]||'').trim();if(i===0&&/team|name/i.test(name))continue;if(!name||S.teams.some(t=>t.name.toLowerCase()===name.toLowerCase()))continue;let code=loginCode();while(S.teams.some(t=>t.code===code)||Object.values(S.passwords||{}).includes(code))code=loginCode();const active=(S.rounds||[]).find(r=>r.active),progress=active?Math.max(0,active.n-1):0;S.teams.push({name,code,points:0,progress:`${progress}/${S.rounds.length}`,status:active?`In round ${active.n}`:'Registered',speed:0,...uniqueLogoFor(name)});if(active?.n>1)S.passwords[`${active.n}-${code}`]=uniqueRoundPassword(code);count++}save();render();toast(`${count} team${count===1?'':'s'} imported with login codes and logos.`)};reader.readAsText(file)}

function questionRound(q){return Number(q.round)||1}
function questionForm(){const opts=(S.rounds||[]).map(r=>`<option value="${r.n}">${esc(r.name)}</option>`).join('');return `<form class="card control-box q-form" onsubmit="addQuestionFromForm(event)"><h2>Add a question</h2><div class="form-grid"><div class="field"><label>Round</label><select id="qRound">${opts}</select></div><div class="field"><label>Question type</label><select id="qType" onchange="toggleQuestionType()"><option value="multiple-choice">Multiple choice</option><option value="typed">Typed answer</option></select></div><div class="field"><label>Points for a correct answer</label><input id="qPoints" type="number" min="0" value="10" required></div></div><div class="field"><label>Question</label><textarea id="qText" rows="2" required placeholder="Type the question"></textarea></div><div class="form-grid" id="questionOptions"><div class="field"><label>Option A</label><input id="qA"></div><div class="field"><label>Option B</label><input id="qB"></div><div class="field"><label>Option C</label><input id="qC"></div><div class="field"><label>Option D</label><input id="qD"></div></div><div class="form-grid"><div class="field"><label>Correct answer</label><input id="qAnswer" required></div><div class="field"><label>Question image or video (optional)</label><input id="qMedia" type="file" accept="image/jpeg,image/png,image/webp,image/gif,video/mp4,video/webm" onchange="uploadQuestionMedia(this.files[0])"><small id="mediaStatus">Small images or video clips up to 1.8 MB; paste a public media link for larger files.</small><label>Or paste a public image/video link</label><input id="qMediaURL" type="url" placeholder="https://…"></div><button class="btn form-submit" type="submit">＋ Save question</button></div><p class="sub small-note">Small uploads are saved in your existing Cloudflare database. For larger clips, paste a public MP4/WEBM or YouTube link.</p></form>`}
function toggleQuestionType(){const typed=$('qType')?.value==='typed';$('questionOptions').style.display=typed?'none':'grid';['qA','qB','qC','qD'].forEach(id=>{const el=$(id);if(el)el.required=!typed})}
async function uploadQuestionMedia(file){if(!file)return;if(file.size>1800000){toast('Media uploads must be 1.8 MB or smaller. Paste a public video link for larger clips.');return}const status=$('mediaStatus');if(status)status.textContent='Uploading…';try{const form=new FormData();form.append('file',file);const res=await fetch('/api/admin/media',{method:'POST',headers:{authorization:`Bearer ${ADMIN_TOKEN}`},body:form}),data=await res.json();if(!res.ok)throw Error(data.error||'Media upload failed');pendingMedia={url:data.url,type:data.type,name:data.name};if(status)status.textContent=`Uploaded: ${data.name}`}catch(e){if(status)status.textContent=e.message;toast(e.message)}}
function questionsPage(){const qs=[...(S.questions||[])];return shell(`${header('Question bank','Add questions, set points, import a CSV, and choose what the audience sees.',`<div class="toolbar">${btn('↑ Upload questions CSV',"$('questionFile').click()",'light')}<input id="questionFile" type="file" accept=".csv,text/csv" hidden onchange="importQuestions(this.files[0])">${btn('↓ CSV template','downloadQuestionTemplate()','light')}</div>`)}${questionForm()}<section class="card table-panel" style="margin-top:16px"><div class="panel-head"><h2>Questions</h2><span class="badge">${qs.length}</span></div>${qs.length?qs.map((q,i)=>`<article class="question"><div class="qtop"><span>${esc(S.rounds.find(r=>r.n===questionRound(q))?.name||fmtRound(questionRound(q)))}</span><span class="correct-key">${Number(q.points??10)} points</span></div><p>${esc(q.text)}</p>${mediaMarkup(q.mediaUrl,q.mediaType)}<div class="answer">${q.options?.length?`Options: ${q.options.map(esc).join(' · ')}<br>`:''}Correct answer: <b>${esc(q.answer)}</b></div><div class="row-actions">${btn(S.projectedQuestionId===q.id?'✓ Projected':'▣ Project to audience',`projectQuestion(${jsarg(q.id)})`,'tiny light')}<button class="small-link" onclick="editQuestion(${jsarg(q.id)})">Edit</button><button class="small-link danger" onclick="deleteQuestion(${jsarg(q.id)})">Delete</button></div></article>`).join(''):`<div class="empty-state"><strong>No questions added yet.</strong><p>Use the form above or upload a CSV with columns: round, question, option_a, option_b, option_c, option_d, answer, points.</p></div>`}</section>`,'Questions')}
function addQuestionFromForm(e){e.preventDefault();const round=Number($('qRound').value),text=$('qText').value.trim(),answer=$('qAnswer').value.trim(),type=$('qType').value,options=type==='typed'?[]:[$('qA').value,$('qB').value,$('qC').value,$('qD').value].map(x=>x.trim()).filter(Boolean);if(!text||!answer)return;if(type==='multiple-choice'&&options.length<2)return toast('Add at least two answer choices.');const points=Math.max(0,Number($('qPoints').value)||0);S.questions.push({id:`q-${crypto.randomUUID()}`,round,text,options,answer,points,type,...((pendingMedia||$('qMediaURL').value.trim())?{mediaUrl:pendingMedia?.url||$('qMediaURL').value.trim(),mediaType:pendingMedia?.type||(/\.(mp4|webm)(?:\?|$)/i.test($('qMediaURL').value)?'video/mp4':'')}: {})});pendingMedia=null;const r=S.rounds.find(x=>x.n===round);if(r)r.q=S.questions.filter(x=>questionRound(x)===round).length;save();render();toast('Question saved.')}
function editQuestion(id){const q=S.questions.find(x=>x.id===id);if(!q)return;const text=prompt('Question text',q.text);if(text===null)return;const answer=prompt('Correct answer',q.answer);if(answer===null)return;const points=prompt('Points',q.points);if(points===null)return;q.text=text.trim();q.answer=answer.trim();q.points=Math.max(0,Number(points)||0);save();render()}
function deleteQuestion(id){if(!confirm('Delete this question?'))return;S.questions=S.questions.filter(q=>q.id!==id);S.rounds.forEach(r=>r.q=S.questions.filter(q=>questionRound(q)===r.n).length);if(S.projectedQuestionId===id)S.projectedQuestionId=null;save();render()}
function projectQuestion(id){S.projectedQuestionId=S.projectedQuestionId===id?null:id;save();render();toast(S.projectedQuestionId?'Question sent to audience screen.':'Audience question cleared.')}
function downloadQuestionTemplate(){download('quiz-master-question-template.csv','round,question,option_a,option_b,option_c,option_d,answer,points,type,media_url,media_type\r\n1,"What is the chemical symbol for gold?",Ag,Au,Fe,Gd,Au,10,multiple-choice,,\r\n')}
function importQuestions(file){if(!file)return;const rd=new FileReader();rd.onload=()=>{const rows=parseCsv(String(rd.result||''));if(!rows.length)return toast('The CSV file is empty.');const headers=rows[0].map(x=>x.trim().toLowerCase().replace(/[\s-]+/g,'_')),hasHeader=headers.some(x=>['question','question_text','prompt'].includes(x));const idx=(names,def)=>{const at=headers.findIndex(x=>names.includes(x));return at<0?def:at};let start=hasHeader?1:0;let added=0;for(const row of rows.slice(start)){const get=(names,def)=>row[idx(names,def)]||'';const rawRound=get(['round','round_number','round_no'],0).trim();let round=Number(rawRound.match(/\d+/)?.[0]);if(!round)round=S.rounds.find(r=>r.name.toLowerCase()===rawRound.toLowerCase())?.n||1;if(!S.rounds.some(r=>r.n===round))continue;const text=get(['question','question_text','prompt'],1).trim(),answer=get(['answer','correct_answer','correct'],6).trim();if(!text||!answer)continue;const options=['a','b','c','d'].map((letter,i)=>get([`option_${letter}`,`option${letter}`,`choice_${letter}`,`option_${i+1}`],i+2).trim()).filter(Boolean);const pointsRaw=get(['points','score','marks'],7);const points=pointsRaw===''?10:Math.max(0,Number(pointsRaw)||0);const type=get(['type','question_type'],8)||(options.length?'multiple-choice':'typed');S.questions.push({id:`q-${crypto.randomUUID()}`,round,text,options:type==='typed'?[]:options,answer,points,type,mediaUrl:get(['media_url','image_url','video_url'],9),mediaType:get(['media_type'],10)});added++}S.rounds.forEach(r=>r.q=S.questions.filter(q=>questionRound(q)===r.n).length);save();render();toast(`${added} question${added===1?'':'s'} imported.`)};rd.readAsText(file)}

function roundsPage(){return shell(`${header('Round controls','Choose the number of rounds and edit each round name, time, and points.')}<div class="hero"><div><div class="eyebrow" style="color:#dad6ff">TOURNAMENT CONTROL</div><h2>${S.running?'Tournament is live':'Tournament paused'}</h2><p>${(S.teams||[]).filter(t=>t.status!=='Complete').length} teams still in play.</p></div>${btn(S.running?'⏸ Pause tournament':'▶ Resume tournament','toggleRun()','light')}</div><section class="card round-count-card"><div><h2>Round setup</h2><p class="sub">Set how many rounds your tournament will have. You can rename every round below.</p></div><div class="round-count-control"><label for="roundCount">Number of rounds</label><input id="roundCount" type="number" min="1" max="20" value="${(S.rounds||[]).length}"><button class="btn tiny" onclick="setRoundCount()">Apply</button></div><small class="sub">Between 1 and 20 rounds. Removing rounds also removes their questions and is blocked if those rounds have answers or are active.</small></section><div class="round-cards">${(S.rounds||[]).map(r=>roundCard(r)).join('')}</div>`,'Rounds')}
function roundCard(r){const qcount=S.questions.filter(q=>questionRound(q)===r.n).length,lines=S.teams.map(t=>({t,p:S.passwords?.[`${r.n}-${t.code}`]})).filter(x=>x.p);return `<article class="card round-card"><div class="round-top"><div class="round-title"><span class="round-n">${r.n}</span><div><strong>${esc(r.name)}</strong><small>${qcount} questions · ${roundMinutes(r.time)} minutes</small></div></div><span class="badge ${r.active?'live':''}">${esc(r.status||'Locked')}</span></div><div class="form-grid round-fields"><div class="field"><label>Round name</label><input value="${esc(r.name)}" onchange="setRound(${r.n},'name',this.value)"></div><div class="field"><label>Time limit (minutes)</label><input type="number" min="1" max="240" value="${roundMinutes(r.time)}" onchange="setRound(${r.n},'time',this.value)"></div><div class="field"><label>Default points</label><input type="number" min="0" value="${Number(r.points??10)}" onchange="setRound(${r.n},'points',this.value)"></div></div><div class="row-actions">${r.active?btn('■ End round now',`endRound(${r.n})`,'tiny'):r.status==='Completed'?`<span class="sub">Round complete</span>`:btn(`▶ Start ${esc(r.name)}`,`startRound(${r.n})`,'tiny')}${lines.length?btn('↓ Password sheet',`downloadRoundPasswords(${r.n})`,'tiny light'):''}</div>${lines.length?`<details class="password-list"><summary>Team-specific round passwords · admin only</summary>${lines.map(({t,p})=>`<div>${logo(t,25)}<strong>${esc(t.name)}</strong><code>${esc(p)}</code><button class="small-link" onclick="copyText('${esc(p)}')">Copy</button></div>`).join('')}</details>`:''}</article>`}
function setRound(n,key,value){const r=S.rounds.find(x=>x.n===n);if(!r)return;if(key==='time')r.time=roundTime(value);else if(key==='points')r.points=Math.max(0,Number(value)||0);else r.name=String(value||fmtRound(n)).trim();r.q=S.questions.filter(q=>questionRound(q)===n).length;save();render()}
function setRoundCount(){const input=$('roundCount'),count=Math.max(1,Math.min(20,Math.floor(Number(input?.value)||1))),current=S.rounds.length;if(count===current){input.value=current;return}if(count<current){const removed=S.rounds.filter(r=>r.n>count);if(removed.some(r=>r.active)){toast('End the active round before removing it.');input.value=current;return}if(removed.some(r=>(S.answers||[]).some(a=>Number(a.round_no)===r.n))){toast('A round with submitted answers cannot be removed.');input.value=current;return}const questionCount=S.questions.filter(q=>questionRound(q)>count).length;if(questionCount&&!confirm(`Removing these rounds will also delete ${questionCount} question(s). Continue?`)){input.value=current;return}S.rounds=S.rounds.filter(r=>r.n<=count);S.questions=S.questions.filter(q=>questionRound(q)<=count);S.readyByRound=Object.fromEntries(Object.entries(S.readyByRound||{}).filter(([n])=>Number(n)<=count));for(const map of [S.passwords,S.roundAccess])if(map)for(const key of Object.keys(map))if(Number(key.split('-')[0])>count)delete map[key];if(!S.rounds.some(r=>S.questions.some(q=>String(q.id)===String(S.projectedQuestionId)&&questionRound(q)===r.n)))S.projectedQuestionId=null}else{for(let n=current+1;n<=count;n++)S.rounds.push({n,name:fmtRound(n),q:0,time:'10:00',points:10,status:'Locked',active:false,passwordRequired:true})}for(const t of S.teams||[]){const oldProgress=Number(String(t.progress||'0/0').split('/')[0])||0,progress=Math.min(oldProgress,count);t.progress=`${progress}/${count}`;t.status=progress>=count?'Complete':progress>0?`In round ${progress+1}`:'Registered'}S.rounds.forEach(r=>r.q=S.questions.filter(q=>questionRound(q)===r.n).length);save();render();toast(`Tournament set to ${count} round${count===1?'':'s'}.`)}
function startRound(n){const r=S.rounds.find(x=>x.n===n);if(!r)return;if(n>1){const prev=S.rounds.find(x=>x.n===n-1);if(prev&&prev.status!=='Completed'){toast(`Finish ${prev.name} before starting this round.`);return}}if(!S.questions.some(q=>questionRound(q)===n)){toast('Add or upload at least one question for this round first.');return}S.rounds.forEach(x=>{if(x.active){x.active=false;x.status='Completed';x.ended=true}});r.active=true;r.ended=false;r.status='In progress';r.deadlineAt=Date.now()+roundMinutes(r.time)*60000;S.running=true;S.passwords=S.passwords||{};if(n>1)for(const t of S.teams)S.passwords[`${n}-${t.code}`]=uniqueRoundPassword(t.code);save();render();toast(n===1?'Round 1 is open. Teams can join without a round password.':'Round opened. Each team now has its own password.')}
function endRound(n){const r=S.rounds.find(x=>x.n===n);if(!r)return;r.active=false;r.ended=true;r.status='Completed';for(const t of S.teams){const p=Number((t.progress||`0/${S.rounds.length}`).split('/')[0])||0;if(p<n){t.progress=`${n}/${S.rounds.length}`;t.status=n>=S.rounds.length?'Complete':`In round ${n+1}`}}save();render();toast('Round closed. Teams are waiting for the next round.')}
function addRound(){const n=Math.max(0,...S.rounds.map(r=>r.n))+1;S.rounds.push({n,name:fmtRound(n),q:0,time:'10:00',points:10,status:'Locked',active:false});for(const t of S.teams){const p=Number((t.progress||'0/0').split('/')[0])||0;t.progress=`${p}/${S.rounds.length}`;if(t.status==='Complete')t.status=`In round ${n}`}save();render()}
function downloadRoundPasswords(n){const rows=[['Team','Team login code',`Round ${n} password`],...S.teams.map(t=>[t.name,t.code,S.passwords?.[`${n}-${t.code}`]||''])];download(`quiz-master-round-${n}-passwords.csv`,rows.map(r=>r.map(csvCell).join(',')).join('\r\n'))}
function toggleRun(){S.running=!S.running;save();render()}

function projectorPage(){const q=S.questions.find(x=>x.id===S.projectedQuestionId);return shell(`${header('Audience projector','This display is public. It shows the live leaderboard and the question selected by the host.',btn('Open projector','openAudience()','light'))}<section class="card control-box"><h2>Live audience preview</h2><p class="sub">${q?`Projected: ${esc(q.text)}`:'Choose a question in the Question Bank to project it.'}</p><div class="project-preview">${audienceContent(true)}</div></section>${btn('Clear projected question','clearProjection()','light tiny')}`,'Projector')}
function clearProjection(){S.projectedQuestionId=null;save();render()}
function settingsPage(){return shell(`${header('Tournament settings','Change the event title, audience visibility, and export every team’s answers.') }<section class="card control-box settings-card"><h2>General</h2><div class="field"><label>Event name</label><input value="${esc(S.quizName||'QUIZ MASTER')}" onchange="S.quizName=this.value.trim()||'QUIZ MASTER';save()"></div><div class="switch-row"><div><strong>Show leaderboard to audience</strong><div class="sub">The projector refreshes automatically.</div></div><button class="switch ${S.leaderboard?'on':''}" onclick="toggleBoard()" aria-label="Toggle leaderboard"></button></div><div class="export-card"><strong>Download participant answers</strong><p>Includes each team’s answer, correct answer, points and answer time.</p>${btn('↓ Export all answers CSV','exportAnswers()','tiny')}</div><div class="export-card"><strong>Branding</strong><p>The site header and page title now display <b>QUIZ MASTER</b>.</p></div></section>`,'Settings')}
function toggleBoard(){S.leaderboard=!S.leaderboard;save();render()}
async function exportAnswers(){try{const res=await api('/api/admin/export.csv');if(!res.ok)throw Error('Export failed');download('quiz-master-answers.csv',await res.text())}catch(e){toast(e.message)}}
function go(tab){S.tab=tab;render()}
function adminPage(){const map={Overview:overview,Teams:teamsPage,Questions:questionsPage,Rounds:roundsPage,Projector:projectorPage,Settings:settingsPage};return (map[S.tab]||overview)()}
function adminLogin(){return `<header class="topbar"><div class="brand"><span class="mark">QM</span><span>QUIZ <b>MASTER</b></span></div></header><main class="team-login"><section class="login-card"><div class="eyebrow">ADMIN ACCESS</div><h1>Sign in to Quiz Master</h1><p class="sub">Manage teams, questions, rounds and the audience projector.</p><div class="field"><label>Admin password</label><input id="adminPassword" type="password" autocomplete="current-password" onkeydown="if(event.key==='Enter')adminSignIn()"></div><button class="btn" onclick="adminSignIn()">Sign in →</button></section></main>`}
async function adminSignIn(){try{const r=await fetch('/api/admin/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({password:$('adminPassword').value})}),d=await r.json();if(!r.ok)throw Error(d.error||'Sign-in failed');ADMIN_TOKEN=d.token;localStorage.setItem('quizMasterAdminToken',ADMIN_TOKEN);S=await api('/api/admin/state');S.tab='Overview';render();startPolling()}catch(e){toast(e.message)}}
function logoutAdmin(){ADMIN_TOKEN='';localStorage.removeItem('quizMasterAdminToken');clearInterval(pollTimer);render()}

function participantLogin(){return `<header class="topbar"><div><div class="brand"><span class="mark">QM</span><span>QUIZ <b>MASTER</b></span></div><p class="tagline">${esc(S.quizName||'Team tournament')}</p></div></header><main class="team-login"><section class="login-card"><div class="waiting-icon">♧</div><div class="eyebrow">TEAM CHECK-IN</div><h1>Join your team</h1><p class="sub">Enter the private login password given to your team by the host.</p><div class="field"><label>Team login password</label><input id="teamCode" maxlength="20" autocomplete="off" placeholder="Example: A7K9P2QX" onkeydown="if(event.key==='Enter')teamSignIn()"></div><button class="btn" onclick="teamSignIn()">Join tournament →</button><p class="hint">Keep your team login and each round password private. Round 1 does not need a round password.</p></section></main>`}
async function teamSignIn(){try{const res=await fetch('/api/team/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({code:$('teamCode').value.trim()})}),d=await res.json();if(!res.ok)throw Error(d.error||'Team login failed');TEAM_TOKEN=d.token;sessionStorage.setItem('quizMasterTeamToken',TEAM_TOKEN);S=Object.assign(d.state,{team:d.team,phase:'waiting',role:'participant'});await refreshTeam();render();startPolling()}catch(e){toast(e.message)}}
async function refreshTeam(){const d=await api('/api/team/state');S=Object.assign(S,d.state,{team:d.team,answers:d.answers,revealAnswers:d.revealAnswers,phase:'waiting',role:'participant'});return d}
function participantWaiting(){const t=S.team||{},progress=Number((t.progress||'0/0').split('/')[0])||0,total=S.rounds?.length||0,r=S.running?(S.rounds||[]).find(x=>x.active&&progress<x.n):null,ready=!!r&&t.readyRound===r.n,complete=progress>=total&&total>0,needsPassword=!!t.needsRoundPassword;return `<header class="topbar"><div><div class="brand"><span class="mark">QM</span><span>QUIZ <b>MASTER</b></span></div><p class="tagline">${esc(S.quizName||'Team tournament')} · Team area</p></div><span class="pill">${S.running?'● Connected':'Host paused'}</span></header><main class="waiting"><section class="card waiting-card"><div class="waiting-icon" style="background:${esc(t.logoColor||logoFor(t.name).logoColor)}18;color:${esc(t.logoColor||logoFor(t.name).logoColor)}">${esc(t.logo||logoFor(t.name).logo)}</div><div class="eyebrow">TEAM WAITING AREA</div><h1>Welcome, ${esc(t.name)}!</h1><p class="sub">Your team is checked in. Watch this page for the next round.</p><span class="team-tag">LOGIN PASSWORD · ${esc(t.code)}</span><div class="progressline" style="margin-top:26px"><i style="width:${total?Math.min(100,progress/total*100):0}%"></i></div><strong>${complete?'All rounds complete':r?ready?(r.allReady?'All teams are ready':`Your team is ready · ${r.readyCount}/${S.teamCount} teams ready`):`${esc(r.name)} is open`:S.running?'Waiting for the host to open a round':'The tournament is paused'}</strong><p class="sub">Progress ${esc(t.progress||`0/${total}`)} · Score ${Number(t.points)||0}</p>${r&&!ready?`<div class="round-entry"><p>Tell the host and audience your team is ready before the questions are shown.</p>${btn('✓ We are ready',`markReady(${r.n})`)}</div>`:r&&ready&&!r.allReady?`<div class="round-entry"><p>Wait here while the other teams mark themselves ready.</p><span class="badge">${r.readyCount}/${S.teamCount} teams ready</span></div>`:r&&r.allReady?`<div class="round-entry"><p>${r.n===1?'Round 1 is ready. No round password is needed.':needsPassword?'Enter your team-specific password for this round.':'The admin has granted your team direct access.'}</p>${needsPassword?`<div class="field"><label>${esc(r.name)} password</label><input id="roundPass" autocomplete="off" placeholder="Round password"></div>`:''}<button class="btn" onclick="enterRound(${r.n})">${r.n===1?'Start Round 1':'Enter round'} →</button></div>`:''}${complete?reviewAnswers():roundFeedback()}<div style="margin-top:22px">${btn('Leave team','leaveTeam()','light tiny')}</div></section></main>`}
function answerCards(rows,final=false){return rows.map(a=>`<article class="question"><div class="qtop"><span>ROUND ${a.round_no}</span><span class="${a.correct?'correct-key':'locked-key'}">${a.correct?'Correct':'Incorrect'} · ${Number(a.points)||0} pts</span></div><p>${esc(a.question_text||a.question_id)}</p><div class="answer">Your answer: <b>${esc(a.answer||'No answer')}</b>${final?`<br>Correct answer: <b>${esc(a.correct_answer||'')}</b>`:''}</div></article>`).join('')}
function roundFeedback(){const rows=(S.answers||[]).filter(a=>a.correct!==null);return rows.length?`<section class="card result-card review"><h2>Completed round feedback</h2><p class="sub">Your answers are locked. Correct answers are shown after all rounds are finished.</p>${answerCards(rows,false)}</section>`:''}
function reviewAnswers(){const rows=S.answers||[];return `<section class="card result-card review"><h2>Final answer review</h2><p class="sub">You’ve finished all rounds. Correct answers are now shown.</p>${answerCards(rows,true)||'<p class="sub">No submitted answers are available.</p>'}</section>`}
async function markReady(n){try{await api('/api/team/ready','POST',{round:n});await refreshTeam();render();startPolling()}catch(e){toast(e.message)}}
async function enterRound(n){try{const pass=n===1?'':$('roundPass')?.value||'',d=await api('/api/team/verify-round','POST',{round:n,password:pass});activeRound=d.round;activeQuestionSet=d.questions;roundStartedAt=Date.now();draftAnswers={};S.phase='play';render();startClock()}catch(e){toast(e.message)}}
function playPage(){const r=activeRound||{},questions=activeQuestionSet||[];return `<header class="topbar"><div><div class="brand"><span class="mark">QM</span><span>QUIZ <b>MASTER</b></span></div><p class="tagline">${esc(S.team?.name||'Team')} · ${esc(r.name||'Round')}</p></div><div class="timer" id="roundTimer">--:-- <span>remaining</span></div></header><main class="question-play"><div class="play-top"><div><div class="eyebrow">${esc(r.name)} · ${questions.length} QUESTIONS</div><strong>Your answers lock when submitted or when time ends.</strong></div></div><div class="progressline"><i style="width:30%"></i></div>${questions.map((q,i)=>`<section class="card play-question" data-question="${esc(q.id)}"><div class="qtop"><span>QUESTION ${String(i+1).padStart(2,'0')}</span><span class="badge">${Number(q.points)||0} points · ${q.type==='typed'?'Typed answer':'Multiple choice'}</span></div>${mediaMarkup(q.mediaUrl,q.mediaType)}<h2>${esc(q.text)}</h2>${q.options?.length?`<div class="choices">${q.options.map((op,j)=>`<button class="choice ${draftAnswers[q.id]===op?'selected':''}" onclick="selectAnswer('${esc(q.id)}','${esc(op).replaceAll("'","&#39;")}')"><b>${String.fromCharCode(65+j)}</b>${esc(op)}</button>`).join('')}</div>`:`<div class="field"><label>Your answer</label><input value="${esc(draftAnswers[q.id]||'')}" oninput="draftAnswers['${esc(q.id)}']=this.value"></div>`}</section>`).join('')}<div class="submit-row">${btn('Submit all answers','submitRound()')}</div><p class="sub" style="text-align:center">You can submit once. Answers cannot be changed after submission.</p></main>`}
function selectAnswer(id,value){draftAnswers[id]=value;document.querySelectorAll(`[data-question="${CSS.escape(id)}"] .choice`).forEach(b=>b.classList.toggle('selected',b.textContent.trim().slice(1).trim()===value))}
async function submitRound(auto=false){const answers=(activeQuestionSet||[]).map(q=>({questionId:q.id,answer:draftAnswers[q.id]||'',elapsedMs:Math.max(0,Date.now()-roundStartedAt)}));try{await api('/api/team/submit-round','POST',{round:activeRound?.n,answers});activeRound=null;activeQuestionSet=[];await refreshTeam();render();toast(auto?'Time is up. Your round is locked.':'Answers submitted and locked.');startPolling()}catch(e){activeRound=null;activeQuestionSet=[];try{await refreshTeam()}catch{}S.phase='waiting';render();toast(e.message)}}
function startClock(){clearInterval(timeTimer);timeTimer=setInterval(()=>{if(S.phase!=='play'||!activeRound?.deadlineAt)return;const remain=Math.max(0,Math.ceil((activeRound.deadlineAt-Date.now())/1000));const el=$('roundTimer');if(el)el.innerHTML=`${String(Math.floor(remain/60)).padStart(2,'0')}:${String(remain%60).padStart(2,'0')} <span>remaining</span>`;if(remain<=2){clearInterval(timeTimer);submitRound(true)}},500)}
function leaveTeam(){TEAM_TOKEN='';sessionStorage.removeItem('quizMasterTeamToken');clearInterval(pollTimer);clearInterval(timeTimer);S={phase:'login'};render()}

function audienceContent(preview=false){const s=S;return `<div class="audience-head"><div><div class="eyebrow">LIVE TOURNAMENT</div><h1>${esc(s.quizName||'QUIZ MASTER')}</h1><p>${s.rounds?.find(r=>r.active)?.name?`● ${esc(s.rounds.find(r=>r.active).name)} is live`:'Tournament standings'}</p></div><span class="badge live">● UPDATING LIVE</span></div>${s.projectedQuestion?`<section class="audience-question"><div class="eyebrow">${esc(s.rounds?.find(r=>r.n===s.projectedQuestion.round)?.name||fmtRound(s.projectedQuestion.round))}</div><h2>${esc(s.projectedQuestion.text)}</h2>${s.projectedQuestion.options?.length?`<div class="audience-options">${s.projectedQuestion.options.map((x,i)=>`<div><b>${String.fromCharCode(65+i)}</b>${esc(x)}</div>`).join('')}</div>`:''}${s.allTeamsComplete?`<div class="audience-answer">Correct answer: <strong>${esc(s.projectedQuestion.answer||'')}</strong></div>`:`<div class="audience-answer muted">Answer revealed when all teams finish all rounds</div>`}</section>`:`<section class="audience-question waiting-project"><h2>${s.allTeamsComplete?'Tournament complete':'Waiting for the host to project a question'}</h2><p>${s.allTeamsComplete?'Final answers are displayed below.':'The live leaderboard will keep updating here.'}</p></section>`}${s.leaderboard?`<section class="audience-board"><div class="panel-head"><h2>🏆 ${active?'Live leaderboard':(s.rounds||[]).some(r=>r.status==='Completed')?'Round leaderboard':'Live leaderboard'}</h2><span class="badge live">${s.teams?.length||0} teams</span></div>${leaderboardTable(false)}</section>`:`<section class="audience-question"><h2>Leaderboard hidden</h2><p>The host has temporarily hidden the standings.</p></section>`}${s.allTeamsComplete&&s.finalQuestions?.length?`<section class="audience-board final-answers"><div class="panel-head"><h2>Questions & correct answers</h2><span class="badge live">All rounds complete</span></div>${s.finalQuestions.map(q=>`<article class="question"><div class="qtop"><span>${esc(s.rounds?.find(r=>r.n===q.round)?.name||fmtRound(q.round))}</span><span class="correct-key">${Number(q.points)||0} points</span></div><p>${esc(q.text)}</p>${q.options?.length?`<div class="answer">Options: ${q.options.map(esc).join(' · ')}</div>`:''}<div class="audience-answer">Correct answer: <strong>${esc(q.answer)}</strong></div></article>`).join('')}</section>`:''}<footer>QUIZ MASTER · Live audience display</footer>`}
function audiencePage(){document.title='QUIZ MASTER · Audience';return `<main class="audience-screen">${audienceContent()}</main>`}

function addStyles(){if(document.getElementById('qmStyles'))return;const s=document.createElement('style');s.id='qmStyles';s.textContent=`.team-logo{display:inline-grid;place-items:center;flex:none;border-radius:11px;background:color-mix(in srgb,var(--logo-color) 15%,white);border:1px solid color-mix(in srgb,var(--logo-color) 28%,white);font-size:20px}.danger{color:#c44949!important}.empty-cell,.empty-state{text-align:center;color:#858999;padding:28px}.empty-state p{max-width:560px;margin:9px auto}.small-note{font-size:11px;line-height:1.6}.quick-actions,.toolbar,.row-actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.quick-actions{margin:18px 0}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.q-form{margin-bottom:16px}.q-form textarea,.q-form input,.q-form select,.round-fields input,.settings-card input{width:100%;border:1px solid var(--line);border-radius:8px;padding:10px;background:#fff;font:inherit;font-size:12px;color:var(--ink)}.form-submit{align-self:end;margin:11px 0}.round-fields{grid-template-columns:1.3fr 1fr 1fr;gap:12px}.password-list{margin-top:14px;padding:12px;background:#f8f7ff;border-radius:10px}.password-list summary{cursor:pointer;color:#5f4fd3;font-weight:700;font-size:11px}.password-list>div{display:flex;align-items:center;gap:8px;padding:8px 0;border-bottom:1px solid #e7e4f6;font-size:11px}.password-list code{margin-left:auto;font-weight:800;letter-spacing:1px}.settings-card{max-width:780px;padding:24px}.round-entry{max-width:380px;margin:18px auto 0;padding:16px;background:#faf9ff;border:1px solid var(--line);border-radius:12px}.round-entry p{font-size:12px;color:var(--muted)}.review{text-align:left;margin-top:22px}.review h2{text-align:center}.submit-row{display:flex;justify-content:flex-end;margin:18px 0}.toast{position:fixed;bottom:24px;left:50%;transform:translate(-50%,20px);background:#232538;color:white;padding:12px 18px;border-radius:10px;opacity:0;pointer-events:none;transition:.2s;z-index:50;box-shadow:0 8px 25px #0003}.toast.show{opacity:1;transform:translate(-50%,0)}.paused{background:#fff0df;color:#b46a18}.audience-screen{min-height:100vh;background:#151724;color:#fff;padding:clamp(20px,5vw,60px)}.audience-screen h1{font-size:clamp(32px,5vw,58px)}.audience-screen .sub,.audience-screen p{color:#a7a9b8}.audience-head{max-width:1150px;margin:0 auto 24px;display:flex;justify-content:space-between;align-items:center;gap:16px}.audience-question,.audience-board{max-width:1150px;margin:0 auto 18px;background:#1d2030;border:1px solid #2b2d3c;border-radius:18px;padding:clamp(18px,3vw,30px)}.audience-question h2{font-size:clamp(22px,3vw,38px);line-height:1.35;margin:8px 0 18px}.audience-options{display:grid;grid-template-columns:1fr 1fr;gap:10px}.audience-options>div{padding:14px;border-radius:10px;background:#272a3b}.audience-options b{margin-right:10px;color:#bcb3ff}.audience-answer{margin-top:18px;padding:14px;border-radius:10px;background:#17372f;color:#8ce2b9;font-size:15px}.audience-answer.muted{background:transparent;color:#9699aa}.audience-board .table td,.audience-board .table th{color:#fff;border-color:#343748}.audience-board .table th{color:#a2a5b4}.audience-board .team-mark{background:#302d49;color:#fff}.audience-board .team-cell{color:white}.audience-board .rankboard{background:transparent;border:0;padding:0}.audience-board .panel-head{margin-bottom:12px}.final-answers .question{border-color:#383a49}.audience-screen footer{text-align:center;color:#707385;padding:12px;font-size:11px}.audience-screen .table-wrap{overflow-x:auto}@media(max-width:650px){.form-grid,.round-fields,.audience-options{grid-template-columns:1fr}.audience-head{align-items:flex-start;flex-direction:column}.toolbar{justify-content:flex-start}.round-card{padding:15px}}`;document.head.append(s)}
function render(){addStyles();document.title=role==='audience'?'QUIZ MASTER · Audience':role==='admin'?'QUIZ MASTER · Admin':'QUIZ MASTER · Teams';if(!root)return;if(role==='admin')root.innerHTML=ADMIN_TOKEN?adminPage():adminLogin();else if(role==='participant')root.innerHTML=S.phase==='play'?playPage():TEAM_TOKEN?participantWaiting():participantLogin();else root.innerHTML=audiencePage()}
function openAudience(){window.open('/audience','quiz-master-audience','noopener')}
function startPolling(){clearInterval(pollTimer);if(role==='audience')pollTimer=setInterval(refreshAudience,2500);if(role==='participant'&&TEAM_TOKEN)pollTimer=setInterval(async()=>{if(S.phase==='waiting'){try{await refreshTeam();render()}catch(e){TEAM_TOKEN='';sessionStorage.removeItem('quizMasterTeamToken');render()}}},2500);if(role==='admin'&&ADMIN_TOKEN)pollTimer=setInterval(async()=>{if(!saving&&!document.activeElement?.matches('input,textarea,select')){try{const tab=S.tab;S=await api('/api/admin/state');S.tab=tab;render()}catch(e){if(/Admin login/.test(e.message))logoutAdmin()}}},5000)}
async function refreshAudience(){try{S=await api('/api/public/state');render()}catch(e){root.innerHTML='<main class="audience-screen"><h1>QUIZ MASTER</h1><p>Connecting to the live tournament…</p></main>'}}
async function boot(){addStyles();if(role==='admin'){if(ADMIN_TOKEN){try{S=await api('/api/admin/state');S.tab='Overview';render();startPolling()}catch{ADMIN_TOKEN='';localStorage.removeItem('quizMasterAdminToken');render()}}else render()}else if(role==='participant'){if(TEAM_TOKEN){try{await refreshTeam();render();startPolling()}catch{TEAM_TOKEN='';sessionStorage.removeItem('quizMasterTeamToken');render()}}else{S={phase:'login'};render()}}else{await refreshAudience();startPolling()}}
function togglePasswordMode(n,required){const r=S.rounds.find(x=>x.n===n);if(!r)return;r.passwordRequired=!!required;save();render()}
function toggleTeamAccess(n,code){S.roundAccess=S.roundAccess||{};const key=`${n}-${code}`;if(S.roundAccess[key])delete S.roundAccess[key];else S.roundAccess[key]=true;save();render()}
function roundCard(r){const qcount=S.questions.filter(q=>questionRound(q)===r.n).length,lines=S.teams.map(t=>({t,p:S.passwords?.[`${r.n}-${t.code}`],direct:!!S.roundAccess?.[`${r.n}-${t.code}`]})),ready=(S.readyByRound?.[String(r.n)]||[]).filter(code=>S.teams.some(t=>t.code===code)).length;return `<article class="card round-card"><div class="round-top"><div class="round-title"><span class="round-n">${r.n}</span><div><strong>${esc(r.name)}</strong><small>${qcount} questions · ${roundMinutes(r.time)} minutes · ${ready}/${S.teams.length} ready</small></div></div><span class="badge ${r.active?'live':''}">${esc(r.status||'Locked')}</span></div><div class="form-grid round-fields"><div class="field"><label>Round name</label><input value="${esc(r.name)}" onchange="setRound(${r.n},'name',this.value)"></div><div class="field"><label>Time limit (minutes)</label><input type="number" min="1" max="240" value="${roundMinutes(r.time)}" onchange="setRound(${r.n},'time',this.value)"></div><div class="field"><label>Default points</label><input type="number" min="0" value="${Number(r.points??10)}" onchange="setRound(${r.n},'points',this.value)"></div></div>${r.n>1?`<label class="access-toggle"><input type="checkbox" ${r.passwordRequired===false?'':'checked'} onchange="togglePasswordMode(${r.n},this.checked)"> Require team passwords for this round</label>`:''}<div class="row-actions">${r.active?btn('■ End round now',`endRound(${r.n})`,'tiny'):r.status==='Completed'?`<span class="sub">Round complete</span>`:btn(`▶ Start ${esc(r.name)}`,`startRound(${r.n})`,'tiny')}${r.n>1?btn('↓ Password sheet',`downloadRoundPasswords(${r.n})`,'tiny light'):''}</div>${r.n>1?`<details class="password-list"><summary>Team access · passwords are admin-only</summary>${lines.map(({t,p,direct})=>`<div>${logo(t,25)}<strong>${esc(t.name)}</strong><code>${direct||r.passwordRequired===false?'Direct access':esc(p||'Not generated yet')}</code><button class="small-link" onclick="toggleTeamAccess(${r.n},${jsarg(t.code)})">${direct?'Require password':'Grant direct access'}</button></div>`).join('')}</details>`:''}</article>`}
function startRound(n){const r=S.rounds.find(x=>x.n===n);if(!r)return;if(n>1){const prev=S.rounds.find(x=>x.n===n-1);if(prev&&prev.status!=='Completed'){toast(`Finish ${prev.name} before starting this round.`);return}}if(!S.questions.some(q=>questionRound(q)===n)){toast('Add or upload at least one question for this round first.');return}S.rounds.forEach(x=>{if(x.active){x.active=false;x.status='Completed';x.ended=true}});r.active=true;r.ended=false;r.status='In progress';r.passwordRequired=r.passwordRequired!==false;r.deadlineAt=Date.now()+roundMinutes(r.time)*60000;S.running=true;S.readyByRound=S.readyByRound||{};S.readyByRound[String(n)]=[];S.projectedQuestionId=S.questions.find(q=>questionRound(q)===n)?.id||null;S.passwords=S.passwords||{};if(n>1)for(const t of S.teams)S.passwords[`${n}-${t.code}`]=uniqueRoundPassword(t.code);save();render();toast(n===1?'Round 1 is open. Teams can join without a round password.':'Round opened. Teams must mark ready before questions appear.')}
function audienceContent(preview=false){const s=S,active=s.rounds?.find(r=>r.active),gate=active?`${active.readyCount||0}/${s.teamCount||0} teams ready`:'';return `<div class="audience-head"><div><div class="eyebrow">LIVE TOURNAMENT</div><h1>${esc(s.quizName||'QUIZ MASTER')}</h1><p>${active?`● ${esc(active.name)} is live · ${gate}`:'Tournament standings'}</p></div><span class="badge live">● UPDATING LIVE</span></div>${s.projectedQuestion?`<section class="audience-question"><div class="eyebrow">${esc(s.rounds?.find(r=>r.n===s.projectedQuestion.round)?.name||fmtRound(s.projectedQuestion.round))}</div>${mediaMarkup(s.projectedQuestion.mediaUrl,s.projectedQuestion.mediaType)}<h2>${esc(s.projectedQuestion.text)}</h2>${s.projectedQuestion.options?.length?`<div class="audience-options">${s.projectedQuestion.options.map((x,i)=>`<div><b>${String.fromCharCode(65+i)}</b>${esc(x)}</div>`).join('')}</div>`:''}${s.allTeamsComplete?`<div class="audience-answer">Correct answer: <strong>${esc(s.projectedQuestion.answer||'')}</strong></div>`:`<div class="audience-answer muted">Answer revealed when all teams finish all rounds</div>`}</section>`:`<section class="audience-question waiting-project"><h2>${active&&!(active.allReady)?'Waiting for all teams to mark ready':s.allTeamsComplete?'Tournament complete':'Waiting for the host to project a question'}</h2><p>${active&&!(active.allReady)?`Ready teams: ${gate}`:s.allTeamsComplete?'Final answers are displayed below.':'The live leaderboard will keep updating here.'}</p></section>`}${s.leaderboard?`<section class="audience-board"><div class="panel-head"><h2>🏆 ${active?'Live leaderboard':(s.rounds||[]).some(r=>r.status==='Completed')?'Round leaderboard':'Live leaderboard'}</h2><span class="badge live">${s.teams?.length||0} teams</span></div>${leaderboardTable(false)}</section>`:`<section class="audience-question"><h2>Leaderboard hidden</h2><p>The host has temporarily hidden the standings.</p></section>`}${s.allTeamsComplete&&s.finalQuestions?.length?`<section class="audience-board final-answers"><div class="panel-head"><h2>Questions & correct answers</h2><span class="badge live">All rounds complete</span></div>${s.finalQuestions.map(q=>`<article class="question">${mediaMarkup(q.mediaUrl,q.mediaType)}<div class="qtop"><span>${esc(s.rounds?.find(r=>r.n===q.round)?.name||fmtRound(q.round))}</span><span class="correct-key">${Number(q.points)||0} points</span></div><p>${esc(q.text)}</p>${q.options?.length?`<div class="answer">Options: ${q.options.map(esc).join(' · ')}</div>`:''}<div class="audience-answer">Correct answer: <strong>${esc(q.answer)}</strong></div></article>`).join('')}</section>`:''}<footer>QUIZ MASTER · Live audience display</footer>`}
const addBaseStyles=addStyles;addStyles=function(){addBaseStyles();if(document.getElementById('qmExtraStyles'))return;const s=document.createElement('style');s.id='qmExtraStyles';s.textContent='.question-media{display:block;max-width:100%;max-height:420px;object-fit:contain;border-radius:12px;margin:10px auto 16px}.access-toggle{display:flex;gap:9px;align-items:center;font-size:12px;padding:9px 0;color:var(--ink)}.leader-row{transition:background .25s ease,transform .25s ease}.round-count-card{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:16px}.round-count-card h2{margin:0 0 5px;font-size:16px}.round-count-card .sub{margin:0}.round-count-card>small{max-width:370px}.round-count-control{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.round-count-control label{font-size:12px;font-weight:700}.round-count-control input{width:80px;border:1px solid var(--line);border-radius:8px;padding:10px;font:inherit}@keyframes leaderRise{from{opacity:.5;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}@media(max-width:700px){.round-count-card{align-items:flex-start;flex-direction:column}}';document.head.append(s)}
function audienceContent(preview=false){const s=S,active=s.rounds?.find(r=>r.active),gate=active?`${active.readyCount||0}/${s.teamCount||0} teams ready`:'';const showQuestion=!!active&&!!active.allReady&&!!s.projectedQuestion&&Number(s.projectedQuestion.round)===Number(active.n),mode=showQuestion?'question':active?'waiting':'leaderboard',rankKey=sortedTeams().map(t=>`${t.name}:${Number(t.points)||0}`).join('|');let stageChanged=false,questionChanged=false;animateAudienceRanks=false;if(!preview&&role==='audience'){stageChanged=lastAudienceMode!==mode;lastAudienceMode=mode;questionChanged=showQuestion&&lastAudienceQuestionId!==s.projectedQuestion.id;lastAudienceQuestionId=showQuestion?s.projectedQuestion.id:'';animateAudienceRanks=lastAudienceRanks!==''&&lastAudienceRanks!==rankKey;lastAudienceRanks=rankKey}const transition=stageChanged?`stage-enter-${mode}`:'';const questionPanel=showQuestion?`<section class="audience-question projector-question ${questionChanged?'question-arrive':''}"><div class="eyebrow">${esc(active.name)} · QUESTION</div>${mediaMarkup(s.projectedQuestion.mediaUrl,s.projectedQuestion.mediaType)}<h2>${esc(s.projectedQuestion.text)}</h2>${s.projectedQuestion.options?.length?`<div class="audience-options">${s.projectedQuestion.options.map((x,i)=>`<div><b>${String.fromCharCode(65+i)}</b>${esc(x)}</div>`).join('')}</div>`:''}</section>`:active?`<section class="audience-question waiting-project"><div class="eyebrow">${esc(active.name)} · GETTING READY</div><h2>Waiting for all teams</h2><p>Teams ready: ${gate}. The question will appear when every team is ready.</p><div class="ready-meter"><span style="width:${Math.min(100,Math.round(100*(active.readyCount||0)/Math.max(1,s.teamCount||0)))}%"></span></div></section>`:`<section class="audience-board leaderboard-focus"><div class="panel-head"><div><div class="eyebrow">${s.allTeamsComplete?'TOURNAMENT COMPLETE':(s.rounds||[]).some(r=>r.status==='Completed')?'ROUND COMPLETE':'LIVE STANDINGS'}</div><h2>🏆 Leaderboard</h2></div><span class="badge live">${s.teams?.length||0} teams</span></div>${s.leaderboard?leaderboardTable(false):'<p class="sub">The host has hidden the leaderboard.</p>'}</section>`;return `<div class="audience-head"><div><div class="eyebrow">LIVE TOURNAMENT</div><h1>${esc(s.quizName||'QUIZ MASTER')}</h1><p>${active?`● ${esc(active.name)} is live · ${gate}`:s.allTeamsComplete?'All rounds complete':'Standings update live'}</p></div><span class="badge live">● UPDATING LIVE</span></div><div class="audience-stage ${transition}">${questionPanel}</div>${s.allTeamsComplete&&s.finalQuestions?.length?`<section class="audience-board final-answers"><div class="panel-head"><h2>Questions & correct answers</h2><span class="badge live">All rounds complete</span></div>${s.finalQuestions.map(q=>`<article class="question">${mediaMarkup(q.mediaUrl,q.mediaType)}<div class="qtop"><span>${esc(s.rounds?.find(r=>r.n===q.round)?.name||fmtRound(q.round))}</span><span class="correct-key">${Number(q.points)||0} points</span></div><p>${esc(q.text)}</p>${q.options?.length?`<div class="answer">Options: ${q.options.map(esc).join(' · ')}</div>`:''}<div class="audience-answer">Correct answer: <strong>${esc(q.answer)}</strong></div></article>`).join('')}</section>`:''}<footer>QUIZ MASTER · Live audience display</footer>`}
function addStageMotionStyles(){if(document.getElementById('qmStageStyles'))return;const style=document.createElement('style');style.id='qmStageStyles';style.textContent=`.audience-screen{position:relative;isolation:isolate;background:radial-gradient(ellipse at 12% 0%,#303052 0,transparent 42%),radial-gradient(ellipse at 92% 18%,#1c4b4c 0,transparent 35%),linear-gradient(140deg,#11131f,#171a2a 55%,#131926)}.audience-screen:before{content:"";position:fixed;inset:0;z-index:-1;pointer-events:none;opacity:.22;background-image:radial-gradient(#b7b6ff 0.7px,transparent 0.7px);background-size:28px 28px;mask-image:linear-gradient(to bottom,black,transparent 85%)}.audience-stage{max-width:1150px;margin:0 auto;min-height:220px;perspective:1000px}.stage-enter-question{animation:boardSlideOut .65s cubic-bezier(.2,.75,.2,1) both}.stage-enter-leaderboard{animation:questionToBoard .6s cubic-bezier(.2,.75,.2,1) both}.stage-enter-waiting{animation:stageFade .45s ease both}.projector-question,.leaderboard-focus{min-height:280px}.projector-question h2{font-size:clamp(30px,5vw,68px);line-height:1.2;text-wrap:balance}.question-arrive{animation:questionIn .65s cubic-bezier(.2,.75,.2,1) both}.waiting-project{min-height:260px;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center}.ready-meter{width:min(540px,90%);height:7px;overflow:hidden;border-radius:9px;background:#ffffff20;margin-top:18px}.ready-meter span{display:block;height:100%;border-radius:inherit;background:linear-gradient(90deg,#9d8cff,#48dfc2);transition:width .6s ease}.rank-shift{animation:rankSettle .6s cubic-bezier(.2,.75,.2,1) both;animation-delay:calc(var(--rank)*55ms)}.audience-board,.audience-question,.final-answers{box-shadow:0 24px 65px #0003;backdrop-filter:blur(10px)}.audience-screen .question,.audience-screen .audience-options>div{transition:transform .25s ease,background .25s ease,border-color .25s ease}.audience-screen .audience-options>div:hover{transform:translateY(-3px);background:#34394f}.card,.question,.btn,.nav{transition:transform .22s ease,box-shadow .22s ease,border-color .22s ease}.card:hover,.question:hover{box-shadow:0 12px 35px #20233716}.btn:hover{transform:translateY(-1px)}@keyframes questionIn{from{opacity:0;transform:translateX(8%) scale(.97);filter:blur(5px)}to{opacity:1;transform:translateX(0) scale(1);filter:blur(0)}}@keyframes boardSlideOut{from{opacity:0;transform:translateX(9%) scale(.98)}to{opacity:1;transform:translateX(0) scale(1)}}@keyframes questionToBoard{from{opacity:0;transform:translateX(-8%) scale(.98)}to{opacity:1;transform:translateX(0) scale(1)}}@keyframes stageFade{from{opacity:0}to{opacity:1}}@keyframes rankSettle{from{opacity:.55;transform:translateY(12px) scale(.985)}to{opacity:1;transform:translateY(0) scale(1)}}@keyframes fadeRise{from{opacity:0;transform:translateY(9px)}to{opacity:1;transform:translateY(0)}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.01ms!important;animation-iteration-count:1!important;scroll-behavior:auto!important;transition-duration:.01ms!important}}`;document.head.append(style)}
addStageMotionStyles();
boot();
